import { Injectable, inject, signal, computed } from '@angular/core';
import { HttpClient, HttpHeaders, HttpErrorResponse } from '@angular/common/http';
import { Observable, throwError, catchError, tap, map } from 'rxjs';
import { environment } from '../../../environments/environment';
import {
  AdminUserSession,
  IndexarDocumentoResponse,
  ListaDocumentosResponse
} from '../models/backoffice.model';

const SESSION_STORAGE_KEY = 'cbb_backoffice_session';

@Injectable({
  providedIn: 'root'
})
export class BackofficeService {
  private readonly http = inject(HttpClient);
  private readonly baseUrl = `${environment.apiUrl}/admin`;

  readonly currentSession = signal<AdminUserSession | null>(this.loadStoredSession());
  readonly isAuthenticated = computed(() => !!this.currentSession()?.adminKey);

  private loadStoredSession(): AdminUserSession | null {
    try {
      const raw = sessionStorage.getItem(SESSION_STORAGE_KEY);
      return raw ? (JSON.parse(raw) as AdminUserSession) : null;
    } catch {
      return null;
    }
  }

  private getAdminHeaders(customKey?: string): HttpHeaders {
    const key = customKey || this.currentSession()?.adminKey || '';
    return new HttpHeaders({
      'X-Admin-Key': key
    });
  }

  /**
   * Valida la clave administrativa contra el backend y guarda la sesión del operador
   */
  login(username: string, role: string, areaDefault: string, adminKey: string): Observable<boolean> {
    const headers = this.getAdminHeaders(adminKey.trim());
    return this.http.get<ListaDocumentosResponse>(`${this.baseUrl}/rag/documentos`, { headers }).pipe(
      tap(() => {
        const session: AdminUserSession = {
          username: username.trim() || 'Administrador CBB',
          role,
          areaDefault,
          adminKey: adminKey.trim(),
          loginTime: new Date().toISOString()
        };
        sessionStorage.setItem(SESSION_STORAGE_KEY, JSON.stringify(session));
        this.currentSession.set(session);
      }),
      map(() => true),
      catchError((err) => this.handleError(err))
    );
  }

  logout(): void {
    sessionStorage.removeItem(SESSION_STORAGE_KEY);
    this.currentSession.set(null);
  }

  /**
   * Obtiene el listado completo de documentos indexados y totales
   */
  listarDocumentos(): Observable<ListaDocumentosResponse> {
    return this.http
      .get<ListaDocumentosResponse>(`${this.baseUrl}/rag/documentos`, {
        headers: this.getAdminHeaders()
      })
      .pipe(catchError((err) => this.handleError(err)));
  }

  /**
   * Sube e indexa un nuevo documento en la base vectorial
   */
  indexarDocumento(params: {
    archivo: File;
    documentoId: string;
    fuente: string;
    areaOrigen: string;
    clasificacionSensibilidad?: string;
  }): Observable<IndexarDocumentoResponse> {
    const formData = new FormData();
    formData.append('archivo', params.archivo);
    formData.append('documento_id', params.documentoId.trim());
    formData.append('fuente', params.fuente.trim());
    formData.append('area_origen', params.areaOrigen);
    formData.append('clasificacion_sensibilidad', params.clasificacionSensibilidad || 'publico');

    return this.http
      .post<IndexarDocumentoResponse>(`${this.baseUrl}/indexar-documento`, formData, {
        headers: this.getAdminHeaders()
      })
      .pipe(catchError((err) => this.handleError(err)));
  }

  /**
   * Elimina un documento y todos sus fragmentos vectoriales de PostgreSQL
   */
  eliminarDocumento(documentoId: string): Observable<{ estado: string }> {
    return this.http
      .delete<{ estado: string }>(
        `${this.baseUrl}/rag/documentos/${encodeURIComponent(documentoId)}`,
        {
          headers: this.getAdminHeaders()
        }
      )
      .pipe(catchError((err) => this.handleError(err)));
  }

  private handleError(error: HttpErrorResponse): Observable<never> {
    let errorMessage = 'No se pudo conectar con el servidor de administración.';
    if (error.status === 401) {
      errorMessage = 'Clave administrativa (X-Admin-Key) inválida o no autorizada.';
    } else if (error.status === 413) {
      errorMessage = 'El archivo supera el límite máximo permitido de 25 MB.';
    } else if (error.status === 415) {
      errorMessage = error.error?.detail || 'Formato de archivo no soportado.';
    } else if (error.error?.detail) {
      errorMessage = error.error.detail;
    }
    return throwError(() => new Error(errorMessage));
  }
}
